        for var in range(2 * n):
            graph[var] = []
        for clause in clauses:
            for var in clause:
                graph[2 * var].append(2 * var + 1)
                graph[2 * var + 1].append(2 * var)
        return graph

    def gaussian_elimination(matrix):
        m, n = len(matrix), len(matrix[0])
        rank = 0
        for i in range(n):
            pivot_row = -1
            for j in range(rank, m):
                if matrix[j][i] != 0:
