            matrix[pivot_row], matrix[rank] = matrix[rank], matrix[pivot_row]
            for j in range(n):
                if j != i and matrix[rank][j] != 0:
                    factor = matrix[rank][j] / matrix[rank][i]
                    for k in range(n):
                        matrix[j][k] -= factor * matrix[rank][k]
            rank += 1
        return rank

